namespace sv_215987a244e242d68d17d5d147ffa58f.Services;

public enum Theme { Light, Dark, System }

/// <summary>
/// Scoped service — one instance per circuit. Holds theme state and
/// notifies all subscribers (interactive islands) when values change.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public Theme Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    /// <summary>
    /// Raised on any property change. Interactive components subscribe
    /// to this and call StateHasChanged.
    /// </summary>
    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@*
    Interactive island placed in the static MainLayout header.
    Because it has @rendermode InteractiveServer it lives inside the
    circuit and shares the scoped ThemeService with every other
    interactive component.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<span class="badge rounded-pill"
      style="background-color: @ThemeSvc.AccentColor; color: white;">
    @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleChange;

    private void HandleChange()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleChange;
}

@*
    Interactive island for quick theme cycling.
    Can be placed anywhere — sidebar, header, etc.
*@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        title="Current: @ThemeSvc.Theme">
    @GetIcon()
</button>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleChange;

    private void CycleTheme()
    {
        ThemeSvc.Theme = ThemeSvc.Theme switch
        {
            Theme.Light  => Theme.Dark,
            Theme.Dark   => Theme.System,
            _            => Theme.Light
        };
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        Theme.Light  => "☀️",
        Theme.Dark   => "🌙",
        _            => "💻"
    };

    private void HandleChange()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleChange;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeSvc

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px; border-color: @ThemeSvc.AccentColor;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var t in Enum.GetValues<Theme>())
            {
                <button class="btn @(ThemeSvc.Theme == t ? "btn-primary" : "btn-outline-primary")"
                        style="--bs-btn-active-bg: @ThemeSvc.AccentColor;
                               --bs-btn-bg: @(ThemeSvc.Theme == t ? ThemeSvc.AccentColor : "transparent")"
                        @onclick="() => ThemeSvc.Theme = t">
                    @t
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-2 mb-3">
            <input type="color" class="form-control form-control-color"
                   value="@ThemeSvc.AccentColor"
                   @onchange="e => ThemeSvc.AccentColor = e.Value?.ToString() ?? "#0d6efd"" />
            <span class="text-muted">@ThemeSvc.AccentColor</span>
        </div>

        <h5 class="card-title">Preview</h5>
        <p>
            Current theme: <strong>@ThemeSvc.Theme</strong><br />
            Accent: <span style="color: @ThemeSvc.AccentColor;">■ @ThemeSvc.AccentColor</span>
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
        => ThemeSvc.OnChange += HandleChange;

    private void HandleChange()
        => InvokeAsync(StateHasChanged);

    public void Dispose()
        => ThemeSvc.OnChange -= HandleChange;
}

